#### Free Energy Class ####
#--------------------------

class FreeEnergy:

  def __init__(self, Nr, N1, N2, N3, Chi12, Chi13, Chi23, C_reg, delta):
    self.Nr = Nr
    self.N1 = N1
    self.N2 = N2
    self.N3 = N3
    self.Chi12 = Chi12
    self.Chi13 = Chi13
    self.Chi23 = Chi23
    self.C_reg = C_reg
    self.delta = delta

    self.alpha1 = N1/Nr
    self.alpha2 = N2/Nr
    self.alpha3 = N3/Nr
    self.ChiN12 = Chi12*Nr
    self.ChiN13 = Chi13*Nr
    self.ChiN23 = Chi23*Nr
    self.ChiN123 = self.ChiN12 - self.ChiN13 - self.ChiN23
    self.C_regN = C_reg*Nr

    self.bin_Chi_c = 0.5*(1./np.sqrt(N1) + 1./np.sqrt(N2))**2
    self.bin_phi_c = np.sqrt(N2)/(np.sqrt(N1)+np.sqrt(N2))
    self.bin_qdepth = self.Chi12/self.bin_Chi_c - 1.

  def F(self, phi):
    phi1 = phi[0]; phi2 = phi[1]; phi3 = 1-phi1-phi2
    return phi1*np.log(phi1)/self.alpha1 + phi2*np.log(phi2)/self.alpha2 + phi3*np.log(phi3)/self.alpha3 + phi1*phi2*self.ChiN12 + phi1*phi3*self.ChiN13 + phi2*phi3*self.ChiN23 + self.C_regN*np.exp(-phi1/self.delta)

  # first derivatives
  def F1(self, phi):
    phi1 = phi[0]; phi2 = phi[1]; phi3 = 1-phi1-phi2
    return (np.log(phi1)+1)/self.alpha1 - (np.log(phi3)+1)/self.alpha3 +             self.ChiN13*(1-2*phi1) + self.ChiN123*phi2             - self.C_regN/self.delta*np.exp(-phi1/self.delta) 

  def F2(self, phi):
    phi1 = phi[0]; phi2 = phi[1]; phi3 = 1-phi1-phi2
    return (np.log(phi2)+1)/self.alpha2 - (np.log(phi3)+1)/self.alpha3 +             self.ChiN23*(1-2*phi2) + self.ChiN123*phi1

  # second derivatives
  def F11(self, phi):
    phi1 = phi[0]; phi2 = phi[1]; phi3 = 1-phi1-phi2
    return 1./(self.alpha1*phi1) + 1./(self.alpha3*phi3) - 2*self.ChiN13 +             (self.C_regN/self.delta**2)*np.exp(-phi1/self.delta)

  def F12(self, phi):
    phi1 = phi[0]; phi2 = phi[1]; phi3 = 1-phi1-phi2
    return 1./(self.alpha3*(phi3)) + self.ChiN123

  def F21(self, phi): return self.F12(phi)

  def F22(self, phi):
    phi1 = phi[0]; phi2 = phi[1]; phi3 = 1-phi1-phi2
    return 1./(self.alpha2*phi2) + 1./(self.alpha3*phi3) - 2*self.ChiN23

  # third derivatives
  def F111(self, phi):
    phi1 = phi[0]; phi2 = phi[1]; phi3 = 1-phi1-phi2
    return -1./(self.alpha1*(phi1)**2) + 1./(self.alpha3*(phi3)**2)             -(self.C_regN/self.delta**3)*np.exp(-phi1/self.delta)

  def F112(self, phi): 
    phi1 = phi[0]; phi2 = phi[1]; phi3 = 1-phi1-phi2 
    return 1./(self.alpha3*(phi3)**2)

  def F121(self, phi): return self.F112(phi)
  def F122(self, phi): return self.F112(phi)
  def F211(self, phi): return self.F112(phi)
  def F212(self, phi): return self.F112(phi)
  def F221(self, phi): return self.F112(phi)

  def F222(self, phi):
    phi1 = phi[0]; phi2 = phi[1]; phi3 = 1-phi1-phi2
    return -1./(self.alpha2*(phi2)**2) + 1./(self.alpha3*(phi3)**2)

  # fourth derivatives
  def F1111(self, phi):
    phi1 = phi[0]; phi2 = phi[1]; phi3 = 1-phi1-phi2
    return 2./(self.alpha1*(phi1)**3) + 2./(self.alpha3*(phi3)**3)             + (self.C_regN/self.delta**4)*np.exp(-phi1/self.delta)

  def F1121(self, phi):
    phi1 = phi[0]; phi2 = phi[1]; phi3 = 1-phi1-phi2
    return 2./(self.alpha3*(phi3)**3)
    
  def F1221(self, phi): return self.F1121(phi)
  def F2221(self, phi): return self.F1121(phi)
  def F1112(self, phi): return self.F1121(phi)
  def F1122(self, phi): return self.F1121(phi)
  def F1222(self, phi): return self.F1121(phi)

  def F2222(self, phi):
    phi1 = phi[0]; phi2 = phi[1]; phi3 = 1-phi1-phi2
    return 2./(self.alpha2*(phi2)**3) + 2./(self.alpha3*(phi3)**3)

  # --- coexistence curve, spinodal, crit. pt ---

  def mu1(self, phi): 
    return self.alpha1*( (1-phi[0])*self.F1(phi) + ( -phi[1])*self.F2(phi) + self.F(phi) )
  def mu2(self, phi): 
    return self.alpha2*( ( -phi[0])*self.F1(phi) + (1-phi[1])*self.F2(phi) + self.F(phi) )
  def mu3(self, phi): 
    return self.alpha3*( ( -phi[0])*self.F1(phi) + ( -phi[1])*self.F2(phi) + self.F(phi) )

  # coexistence curve         
  def dF(self, phi, phi1_a):
    phi_a = np.array([phi1_a, phi[0]]); # phi1_a, phi2_a
    phi_b = np.array([phi[1], phi[2]]); # phi1_b, phi2_b
    return np.array([ (self.mu1(phi_a) - self.mu1(phi_b)),    (self.mu2(phi_a) - self.mu2(phi_b))*self.alpha1/self.alpha2,         (self.mu3(phi_a) - self.mu3(phi_b))*self.alpha1/self.alpha3 ])
  # spinodal curve
  def d2F(self, phi): return self.F11(phi)*self.F22(phi)-self.F12(phi)*self.F21(phi)

  # critical point curve
  def d3F(self, phi): 
    return self.F111(phi)*self.F22(phi)**2 - 3*self.F112(phi)*self.F12(phi)*self.F22(phi)            + 3*self.F122(phi)*self.F12(phi)**2 - self.F11(phi)*self.F12(phi)*self.F222(phi)

  def critical_point(self, phi): 
    return np.array([self.d2F(phi), self.d3F(phi)])
    
    
  def d2F_opt(self, phi):
    phi1, phi2 = phi
    phi3 = 1 - phi1 - phi2
    A1, A2, A3 = self.alpha1*phi1, self.alpha2*phi2, self.alpha3*phi3
    
    L = (A3 + A1 - 2*A1*A3*self.ChiN13 + A1*A3*self.C_regN / self.delta**2 * np.exp(-phi1 / self.delta))         * (A3 + A2 - 2 * A2 * A3 * self.ChiN23)
        
    R = A1 * A2 * (1 + A3*self.ChiN123)**2
    
    return L - R
  def d3F_opt(self, phi):
    phi1, phi2 = phi
    phi3 = 1 - phi1 - phi2
    A1, A2, A3 = self.alpha1*phi1, self.alpha2*phi2, self.alpha3*phi3
    B1, B2, B3 = self.alpha1*phi1**2, self.alpha2*phi2**2, self.alpha3*phi3**2
    
    delta = self.delta
    
    One = A1 * B2 * (B1 - B3 - B1*B3*self.C_regN/delta**3*np.exp(-phi1/delta))*(A3 + A2 - 2*A2*A3*self.ChiN23)**2
    Two = 3*A1*A2**2*B1*B2*(1 + A3*self.ChiN123)**2
    
    Three=A2**2*B1*(A3 + A1 - 2*A1*A3*self.ChiN13 + A1*A3*self.C_regN/delta**2 * np.exp(-phi1/delta))            *(1 + A3*self.ChiN123)*(B2-B3)
    Four= 3*A1*A2*B1*B2*(1 + A3*self.ChiN123)*(A3 + A2 - 2*A2*A3*self.ChiN23)
    
    return One + Two - Three - Four

  def critical_point_opt(self, phi):
        return np.array([self.d2F_opt(phi), self.d3F_opt(phi)])
        
  # --- two component free energies (polymer, non-solvent) ---
  def F_bin(self, phi, F, S): 
        
    if F > S:
        raise Exception("Please input parameters in numerically ascending order!")
    
    if F == 1 and S == 2: 
        alpha1, alpha2, Chi = self.alpha1, self.alpha2, self.ChiN12
        
    if F == 1 and S == 3:
        alpha1, alpha2, Chi = self.alpha1, self.alpha3, self.ChiN13
    
    if F == 2 and S == 3:
        alpha1, alpha2, Chi = self.alpha2, self.alpha3, self.ChiN23
        
    return phi*np.log(phi)/alpha1 + (1-phi)*np.log(1-phi)/alpha2 + Chi*phi*(1-phi) #+ self.C_regN*np.exp(-phi/self.delta)

  def F1_bin(self, phi, F, S):
    
    if F > S:
        raise Exception("Please input parameters in numerically ascending order!")
    
    if F == 1 and S == 2: 
        alpha1, alpha2, Chi = self.alpha1, self.alpha2, self.ChiN12
        
    if F == 1 and S == 3:
        alpha1, alpha2, Chi = self.alpha1, self.alpha3, self.ChiN13
    
    if F == 2 and S == 3:
        alpha1, alpha2, Chi = self.alpha2, self.alpha3, self.ChiN23
    
    return (np.log(phi)+1)/alpha1 - (np.log(1-phi)+1)/alpha2             + Chi*(1-2*phi) - self.C_regN/self.delta*np.exp(-phi/self.delta)

  def F11_bin(self, phi): 
    return 1./(self.alpha1*phi) + 1./(self.alpha2*(1-phi))       - 2.*self.ChiN12 + self.C_regN/self.delta**2*np.exp(-phi/self.delta)

  def F11_bin_opt(self, phi, F, S):
    if F > S:
        raise Exception("Please input parameters in numerically ascending order!")
    
    if F == 1 and S == 2: 
        alpha1, alpha2, Chi = self.alpha1, self.alpha2, self.ChiN12
        
    if F == 1 and S == 3:
        alpha1, alpha2, Chi = self.alpha1, self.alpha3, self.ChiN13
    
    if F == 2 and S == 3:
        alpha1, alpha2, Chi = self.alpha2, self.alpha3, self.ChiN23
    
    A1 = phi * alpha1
    A2 = (1-phi) * alpha2
    
    return A2 + A1 - 2*A1*A2*Chi + A1*A2*self.C_regN/self.delta**2*np.exp(-phi/self.delta)
    
  # binary phase coexistence calculation when phi3 = 0
  def binodal_bin(self, phi, F, S): 
    phi_a = phi[0]; phi_b = phi[1]
    d_phi = phi_a - phi_b
    nu_a = (self.bin_phi_c-phi_b)/d_phi
    nu_b = 1-nu_a
    F_bma = self.F_bin(phi_b, F, S) - self.F_bin(phi_a, F, S)
    dF_dphi_a = nu_a/d_phi*F_bma + nu_a*self.F1_bin(phi_a, F, S)
    dF_dphi_b = nu_b/d_phi*F_bma + nu_b*self.F1_bin(phi_b, F, S)
    return np.array([dF_dphi_a, dF_dphi_b])


  def binodal_bin_opt(self, phi, F, S):
        phi_a, phi_b = phi
        phi_c = self.bin_phi_c
        F_bma = self.F_bin(phi_b, F, S) - self.F_bin(phi_a, F, S)
        
        if F > S:
            raise Exception("Please input parameters in numerically ascending order!")
    
        if F == 1 and S == 2: 
            alpha1, alpha2, Chi = self.alpha1, self.alpha2, self.ChiN12

        if F == 1 and S == 3:
            alpha1, alpha2, Chi = self.alpha1, self.alpha3, self.ChiN13

        if F == 2 and S == 3:
            alpha1, alpha2, Chi = self.alpha2, self.alpha3, self.ChiN23

        A = alpha1 * phi_a * (phi_c - phi_b) * F_bma
        B = (phi_a - phi_b) * (phi_c-phi_b) * (1 - alpha1*phi_a/alpha2 - alpha1 / alpha2 * phi_a * np.log(1-phi_a) + alpha1 * phi_a * Chi * (1-2*phi_a))
        C = alpha1 * phi_b * (phi_a - phi_c) * F_bma
        D = ((phi_a - phi_b)**2 - (phi_a-phi_b)*(phi_c-phi_b)) * (1-alpha1*phi_b/alpha2 - alpha1/alpha2*phi_b*np.log(phi_b)                                                                  + alpha1 * phi_a * Chi * (1 - 2*phi_b))
        
        return np.array([A+B, C+D])


