#### Extra Functions ####
#------------------------


def recBis(f, a, b, tol = 1e-10, numCall = 0, maxCall = 100, args = ()):
    if numCall >= maxCall:
        raise Exception("Maximum Recursion Reached on function recBis")
        return -1
    
    c = (a+b)/2
    
    if abs(f(c, *args)) < tol:
        return c  
    
    if f(c, *args)*f(a, *args) > 0:
        return recBis(f, c, b, numCall = numCall+1, args = args, tol = tol)
    
    else:
        return recBis(f, c, a, numCall = numCall+1, args = args, tol = tol)


def recBisStart(f, a, args = (), tol = 1e-10):
    s = np.linspace(a, 1-a, 100)

    for i in range(100):
        if f(a,*args)*f(s[i], *args) < 0:
            return recBis(f, s[i], a, tol = tol, args = args)
    
    return -1

def badComposition(phi_c, crit_pt_err):
    if np.any(phi_c < -1e-3):
        return True
    
    if np.any(phi_c > 1):
        return True
    
    if np.sum(phi_c)> 1+1e-2:
        return True

    if crit_pt_err > 1e-3:
        return True
    
    else:
        return False

def checkAccuracy(f, x, args = ()):
    return -np.log10(np.linalg.norm(f(x, *args)))


