class PhaseDiagram: 
    def __init__(self, TFH, point = None):
        self.TFH = TFH
        self.PointBool = False
        if point != None:
            self.PointBool = True
            self.point = point
        print("\n\n") 
        print("----Evaluating Binary Systems----")
        self.binarySystemSpinodalAnalysis()
        self.printCase()
        print("\n\n----Solving For an Initial Critical Point----")
        self.critical()
        print("\n\n----Solving For the Spinodal Curve----")
        self.ternarySpinodalCurves()
        print("\n\n----Searching Spinodal Curve For Potential Critical Points----")
        self.critPostSpin()
        print("\n\n----Solving For the Binodal Curve----")
        self.binarySystemBinodalAnalysis()
        self.ternaryBinodalCurves()
        if self.PointBool:
            print("\n\n----Determining Phase Solution(s)----")
            self.PointAnalysis()
        print("\n\n----Plotting the Ternary Phase Diagram----")
        self.plotPhaseDiagram()
        print("\n\n")


#--------------------------------
####  Binary Case Evaluation ####
#--------------------------------

def binarySystemSpinodalAnalysis(self):
    TFH = self.TFH

    #Determine Finite Miscibility for Solvent/Non-solvent
    self.FM23 = True 
    NS_spinHigh = 1-recBisStart(TFH.F11_bin_opt, 0, args = (2,3), tol = 1e-10)
    NS_spinLow = 1-recBisStart(TFH.F11_bin_opt, 1, args = (2,3), tol = 1e-10)

    if NS_spinHigh - NS_spinLow < 1e-2:
        self.FM23 = False
    else:
        self.NS_spinHigh = NS_spinHigh
        self.NS_spinLow = NS_spinLow


    #Determine Finite Miscibility for Polymer/Non-solvent
    self.FM12 = True 
    PN_spinLow = recBisStart(TFH.F11_bin_opt, 0, args = (1,2), tol = 1e-10)
    PN_spinHigh = recBisStart(TFH.F11_bin_opt, 1, args = (1,2), tol = 1e-10)

    if PN_spinHigh - PN_spinLow < 1e-2:
        self.FM12 = False
    else:
        self.PN_spinHigh = PN_spinHigh
        self.PN_spinLow = PN_spinLow


    #Determine Finite Miscibility for Polymer/Solvent 
    self.FM13 = True  
    PS_spinLow = recBisStart(TFH.F11_bin_opt, 0, args = (1,3), tol = 1e-10)
    PS_spinHigh = recBisStart(TFH.F11_bin_opt, 1, args = (1,3), tol = 1e-10)

    if PS_spinHigh - PS_spinLow < 1e-2:
        self.FM13 = False
    else:
        self.PS_spinHigh = PS_spinHigh
        self.PS_spinLow = PS_spinLow

    self.s = np.sum([self.FM12, self.FM23, self.FM13])
    return

setattr(PhaseDiagram, "binarySystemSpinodalAnalysis", binarySystemSpinodalAnalysis)

def printCase(self):
    FM12 = self.FM12
    FM13 = self.FM13
    FM23 = self.FM23

    Title =     "Case 1: Finite Miscibility between Polymer and Non-solvent"
    if FM12 and not FM23 and not FM13:
        print(Title)

    Title =     "Case 2: Finite Miscibility between Solvent and Non-solvent"
    if not FM12 and FM23 and not FM13:
        print(Title)

    Title =     "Case 3: Finite Miscibility between Polymer and Solvent"
    if not FM12 and not FM23 and FM13:
        print(Title)

    Title =     "Case 4: Finite Miscibility between Polymer/Non-solvent and Solvent/Non-solvent"
    if FM12 and FM23 and not FM13:
        print(Title)

    Title =     "Case 5: Finite Miscibility between Polymer/Non-solvent and Polymer/Solvent"
    if FM12 and not FM23 and FM13:
        print(Title)

    Title =     "Case 6: Finite Miscibility between Solvent/Non-solvent and Polymer/Solvent"
    if not FM12 and FM23 and FM13:
        print(Title)

    Title =     "Case 7: Finite Miscibility between Solvent/Non-solvent and Polymer/Solvent and Polymer/Non-solvent"
    if FM12 and FM23 and FM13:
        print(Title)

    Title =     "Case 8: No Finite Miscibility"
    if not FM12 and not FM23 and not FM13:
        print(Title)

    return

setattr(PhaseDiagram, "printCase", printCase)

def binarySystemBinodalAnalysis(self):
    TFH = self.TFH
    if self.FM12:
        phia = np.linspace(self.PN_spinHigh, 1-1e-50, 100)
        phib = np.linspace(1e-50, self.PN_spinLow, 100)
        #print(phia,phib)
        phi_p = list()
        for i in range(100):
            for j in range(100):
                if np.linalg.norm(TFH.binodal_bin([phia[i], phib[j]], 1, 2)) < 7:
                    phi_t = [phia[i], phib[j]]
                    #print(phi_t)
                    phi_p.append(phi_t)
#                    if i==99 and j==99:
                        
        accuracy = 0
        ans = []
        for i in range(len(phi_p)):
            newAns = opt.fsolve(TFH.binodal_bin, [phi_p[i][0], phi_p[i][1]], args = (1,2))
            newAccuracy = checkAccuracy(TFH.binodal_bin, newAns, args = [1,2])
            # following three lines of code are for debugging
            #acc = np.zeros(9801)
            #acc[i]=accuracy
            #print(i)
            #np.savetxt('help.txt',acc)
            if accuracy < newAccuracy and newAns[0] > self.PN_spinHigh and newAns[1] < self.PN_spinLow:
                ans = newAns
                #print(ans,len(ans))
                #print(len(phi_p))
                accuracy = newAccuracy
        self.PN_binHigh, self.PN_binLow = ans
        print(ans,'for N=',N1)
        print(f"Polymer/Non-solvent Binodal Points {i}  {self.PN_binHigh:.4}   {self.PN_binLow:.4}")
        print(f"\tAccuracy: {checkAccuracy(TFH.binodal_bin, [self.PN_binHigh, self.PN_binLow], args = [1,2]):.4}")

    if self.FM23:
        phia = np.linspace(1e-18, 1-self.NS_spinHigh, 100)
        phib = np.linspace(1-self.NS_spinLow, 1-1e-18, 100)
        phi_p = list()
        for i in range(100):
            for j in range(100):
                if np.linalg.norm(TFH.binodal_bin([phia[i], phib[j]], 2, 3)) < .05:
                    phi_t = [phia[i], phib[j]]
                    phi_p.append(phi_t)

        phia = 0
        phib = 0

        for i in range(len(phi_p)):
            phia += phi_p[i][0]
            phib += phi_p[i][1]

        if len(phi_p) != 0:
            phia /= len(phi_p)
            phib /= len(phi_p)
        else:
            phia = (1-self.NS_spinHigh)/2
            phib = (1-self.NS_spinLow + 1)/2

        self.NS_binHigh, self.NS_binLow = 1 - opt.fsolve(TFH.binodal_bin, [phia, phib], args = (2, 3))
        print(f"Solvent/Non-solvent Binodal Points   {self.NS_binHigh:.4}   {self.NS_binLow:.4}")
        print(f"\tAccuracy: {checkAccuracy(TFH.binodal_bin, [self.NS_binHigh, self.NS_binLow], args = [2,3]):.4}")
        print(self.NS_binHigh)
    if self.FM13:
        phia = np.linspace(self.PS_spinHigh, 1-1e-18, 100)
        phib = np.linspace(1e-18, self.PS_spinLow, 100)
        phi_p = list()
        for i in range(100):
            for j in range(100):
                if np.linalg.norm(TFH.binodal_bin([phia[i], phib[j]], 1, 3)):
                    phi_t = [phia[i], phib[j]]
                    phi_p.append(phi_t)

        phia = 0
        phib = 0
        for i in range(len(phi_p)):
            phia += phi_p[i][0]
            phib += phi_p[i][1]

        if len(phi_p) != 0:
            phia /= len(phi_p)
            phib /= len(phi_p)
        else:
            phia = (self.PS_spinHigh + 1)/2
            phib = (self.PS_spinLow)/2


        self.PS_binHigh, self.PS_binLow = opt.fsolve(TFH.binodal_bin, [phia, phib], args = (1, 3))
        print(f"Polymer/Solvent Binodal Points   {self.PS_binHigh:.4}   {self.PS_binLow:.4}")

setattr(PhaseDiagram, "binarySystemBinodalAnalysis", binarySystemBinodalAnalysis)




#------------------------
#### Critical Points ####
#------------------------

def critical(self):
    TFH = self.TFH
    phi_guess = np.array([TFH.bin_phi_c, np.exp(-TFH.bin_qdepth)]);

    phi_c = opt.fsolve( TFH.critical_point, phi_guess, xtol=1e-10 )
    crit_pt_err = np.linalg.norm( TFH.critical_point(phi_c) )    

    if ( np.any(phi_c < 0) or np.any(phi_c > 1) or np.sum(phi_c)< 0. or np.sum(phi_c)> 1. ):
        print("\nATTENTION: Unable to find an appropriate guess value for critical point")
        phi_c = input("Please enter a guess value (e.g. .1,.6) or hit enter to use the default (.33,.33)")
        if phi_c == "":
            phi_c = np.array([1/3,1/3])
        else:
            phi_c = phi_c.split(",")
            first = float(phi_c[0])
            second= float(phi_c[1])
            phi_c = np.array([first, second])

    phi_c =opt.fsolve(TFH.critical_point_opt,  phi_c, xtol=1e-10)
    crit_pt_err = np.linalg.norm( TFH.critical_point_opt(phi_c) )
    BAD_CRIT = badComposition(phi_c, crit_pt_err)

    self.phi1_c = phi_c[0]
    self.phi2_c = phi_c[1]
    self.phi3_c = 1-phi_c[0] - phi_c[1]


    if BAD_CRIT:
        print("WARNING! Bad Critical Point Solution\n", phi_c, crit_pt_err)
    else:
        print(f"Critical Point {self.phi1_c:.4} {self.phi2_c:.4} {self.phi3_c:.4}\n\tAccuracy: {-np.log10(crit_pt_err):.4}")


# For Searching Spinodal Curves for Critical Points
def critPostSpin(self):
    TFH = self.TFH
    
    if self.s == 1:
        if checkAccuracy(TFH.critical_point_opt, [self.phi1_c, self.phi2_c])>10:
            self.phi_c1 = [self.phi1_c, self.phi2_c]
            print(f"Critical Point: {self.phi_c1[0]:.4} {self.phi_c1[1]:.4} {1-self.phi_c1[0]-self.phi_c1[1]:.4}                   \n\tAccuracy: {checkAccuracy(TFH.critical_point_opt, self.phi_c1):.4}")
            return
    
    if self.s > 0:
        phi = self.phi_s1

        phi_p = list()

        for i in range(100,len(phi)-100):
            if checkAccuracy(TFH.d3F_opt, phi[i, :-1]) > 4:
                phi_p.append(phi[i, :-1])
                
                
        
        if len(phi_p) > 0:
            phi_g = np.zeros(2)
            for i in range(len(phi_p)):
                phi_g += phi_p[i]
            phi_g /= len(phi_p)

        else:
            print("Method 2")
            phi_g = (phi[0,:-1] + phi[-1,:-1])/2

        self.phi_c1 = opt.fsolve(TFH.critical_point_opt, phi_g)
        crit_pt_err = np.linalg.norm(TFH.critical_point_opt(self.phi_c1))

        if badComposition(self.phi_c1, crit_pt_err):
            print("WARNING! Bad First Critical Point Solution\n", self.phi_c1, crit_pt_err, "\n")
        else:
            print(f"First Critical Point {self.phi_c1[0]:.4} {self.phi_c1[1]:.4} {1-self.phi_c1[0]-self.phi_c1[1]:.4}\n\tAccuracy: {-np.log10(crit_pt_err):.4}")
            print('true')

    if self.s > 1:
        phi = self.phi_s2

        phi_p = list()

        for i in range(100,len(phi)-100):
            if checkAccuracy(TFH.d3F_opt, phi[i, :-1]) > 4:
                phi_p.append(phi[i, :-1])

        if len(phi_p) > 0:
            phi_g = np.zeros(2)
            for i in range(len(phi_p)):
                phi_g += phi_p[i]
            phi_g /= len(phi_p)
            
        else:
            print("Method 2")
            phi_g = (phi[0,:-1] + phi[-1,:-1])/2

        self.phi_c2 = opt.fsolve(TFH.critical_point_opt,phi_g)
        crit_pt_err = np.linalg.norm(TFH.critical_point_opt(self.phi_c2))

        if badComposition(self.phi_c2, crit_pt_err):
            print("WARNING! Bad Second Critical Point Solution\n", self.phi_c2, crit_pt_err, "\n")
        else:
            print(f"Second Critical Point {self.phi_c2[0]:.4} {self.phi_c2[1]:.4} {1-self.phi_c2[0]-self.phi_c2[1]:.4}\n\tAccuracy: {-np.log10(crit_pt_err):.4}")


    if self.s > 2:
        phi = self.phi_s3

        phi_p = list()

        for i in range(100,len(phi)-100):
            if checkAccuracy(TFH.critical_point_opt, phi[i, :-1]) > 4:
                phi_p.append(phi[i, :-1])

        if len(phi_p) > 0:
            phi_g = np.zeros(2)
            for i in range(len(phi_p)):
                phi_g += phi_p[i]
            phi_g /= len(phi_p)
        else:
            print("Method 2")
            phi_g = phi[500,:-1]

        self.phi_c3 = opt.fsolve(TFH.critical_point_opt,phi_g)
        crit_pt_err = np.linalg.norm(TFH.critical_point_opt(self.phi_c3))

        if badComposition(self.phi_c3, crit_pt_err):
            print("WARNING! Bad Third Critical Point Solution\n", self.phi_c3, crit_pt_err, "\n")
        else:
            print(f"Third Critical Point {self.phi_c3[0]:.4} {self.phi_c3[1]:.4} {1-self.phi_c3[0]-self.phi_c3[1]:.4}\n\tAccuracy: {-np.log10(crit_pt_err):.4}")
            
