def ternarySpinodalCurves(self):
    FM12 = self.FM12
    FM13 = self.FM13
    FM23 = self.FM23

    
    if FM12 and not FM23 and not FM13:
        print(f"Polymer/Non-solvent Spinodal Points   {self.PN_spinLow:.4}   {self.PN_spinHigh:.4}")
        self.phi_s1 = self.Case1()

    if not FM12 and FM23 and not FM13:
        print(f"Solvent/Non-Solvent Spinodal Points   {self.NS_spinLow:.4}   {self.NS_spinHigh:.4}")
        self.phi_s1 = self.Case2()

    if not FM12 and not FM23 and FM13:
        print(f"Polymer/Solvent Spinodal Points   {self.PS_spinLow:.4}   {self.PS_spinHigh:.4}")
        self.phi_s1 = self.Case3()

    if FM12 and FM23 and not FM13:
        print(f"Polymer/Non-solvent Spinodal Points   {self.PN_spinLow:.4}   {self.PN_spinHigh:.4}")
        print(f"Solvent/Non-Solvent Spinodal Points   {self.NS_spinLow:.4}   {self.NS_spinHigh:.4}")
        self.phi_s1, self.phi_s2 = self.Case4()
        #self.phi_s1, self.phi_s2 = self.Case1(), self.Case2()

    if FM12 and not FM23 and FM13:
        print(f"Polymer/Non-solvent Spinodal Points   {self.PN_spinLow:.4}   {self.PN_spinHigh:.4}")
        print(f"Polymer/Solvent Spinodal Points       {self.PS_spinLow:.4}   {self.PS_spinHigh:.4}")
        self.phi_s1, self.phi_s2 = self.Case5()

    if not FM12 and FM23 and FM13:
        print(f"Solvent/Non-Solvent Spinodal Points   {self.NS_spinLow:.4}   {self.NS_spinHigh:.4}")
        print(f"Polymer/Solvent Spinodal Points       {self.PS_spinLow:.4}   {self.PS_spinHigh:.4}")
        self.phi_s1, self.phi_s2 = self.Case6()

    if FM12 and FM23 and FM13:
        print(f"Polymer/Non-solvent Spinodal Points   {self.PN_spinLow:.4}   {self.PN_spinHigh:.4}")
        print(f"Polymer/Solvent Spinodal Points       {self.PS_spinLow:.4}   {self.PS_spinHigh:.4}")
        print(f"Solvent/Non-Solvent Spinodal Points   {self.NS_spinLow:.4}   {self.NS_spinHigh:.4}")
        self.phi_s1, self.phi_s2, self.phi_s3 = self.Case7()
        #self.phi_s1, self.phi_s2, self.phi_s3 = self.Case7()


    return

setattr(PhaseDiagram, "ternarySpinodalCurves", ternarySpinodalCurves)

def Case1(self):
    TFH = self.TFH
    steps = 2000
    n = 0
    Printed = True
    
    if self.PN_spinLow > self.phi1_c:
        steps = int(steps/2)
        phi1_array = np.linspace(self.phi1_c+1e-3, self.PN_spinHigh, steps)
        phi2_array = np.zeros(steps)
        spinodal = lambda phi2, phi1: TFH.d2F_opt(([phi1, phi2]))

        phi_init = self.phi2_c

        for i in range(steps):
            phi_init = opt.fsolve(spinodal, phi_init, args = (phi1_array[i]))[0]
            phi2_array[i] = phi_init
            if checkAccuracy(spinodal, phi2_array[i], args = [phi1_array[i]]) < 4:
                print("\n**Warning: Spinodal May Be Inaccurate**\n" if not Printed else "", end = "") 
                n+=1
                Printed = True

        if Printed:
            print("\tNumber of Spinodal Points that did not converge:", n, "\n")
        
        phi_s1L = np.vstack([phi1_array, phi2_array, 1-phi1_array-phi2_array]).T
        
        phi3_array = np.linspace(1e-3, self.phi3_c, steps)
        phi1_array = np.zeros(steps)
        phi2_array = np.zeros(steps)
        spinodal = lambda phi1, phi3: TFH.d2F_opt(np.array([phi1, 1-phi1-phi3]))
        
        phi_init = self.PN_spinLow
        
        for i in range(steps):
            phi_init = opt.fsolve(spinodal, phi_init, args = (phi3_array[i]))[0]
            phi1_array[i] = phi_init
            phi2_array[i] = 1-phi_init-phi3_array[i]
        
        phi_s1R = np.vstack([phi1_array, phi2_array, 1-phi1_array-phi2_array]).T
        
        return np.vstack([phi_s1R, phi_s1L])
        
    else:
        phi1_array = np.linspace(self.PN_spinLow+1e-3, self.PN_spinHigh, steps)
        phi2_array = np.zeros(steps)
        spinodal = lambda phi2, phi1: TFH.d2F_opt(([phi1, phi2]))

        phi_init = self.phi2_c

        for i in range(steps):
            phi_init = opt.fsolve(spinodal, phi_init, args = (phi1_array[i]))[0]
            phi2_array[i] = phi_init

            if checkAccuracy(spinodal, phi2_array[i], args = [phi1_array[i]]) < 4:
                print("\n**Warning: Spinodal May Be Inaccurate**\n" if not Printed else "", end = "") 
                n+=1
                Printed = True

        if Printed:
            print("\tNumber of Spinodal Points that did not converge:", n, "\n")

        phi1_array = np.insert(phi1_array, 0, self.PN_spinLow)
        phi2_array = np.insert(phi2_array, 0, 1-self.PN_spinLow)
    return np.vstack([phi1_array, phi2_array, 1-phi1_array-phi2_array]).T  
    
