def ternaryBinodalCurves(self):
    TFH = self.TFH
    FM12 = self.FM12
    FM13 = self.FM13
    FM23 = self.FM23
    steps = 2000
    n = 0
    Printed = False
    if FM12 and not FM23 and not FM13:
        phi1a_arr = np.linspace(self.PN_binHigh, self.phi_c1[0]+1e-3, steps)
        #phi1a_arr = np.zeros(steps)
        phi2a_arr = np.zeros(steps)
        phi1b_arr = np.zeros(steps)
        phi2b_arr = np.zeros(steps)
        #binodal = lambda phi, phi3: TFH.dF(phi, 1-phi3-phi[0])
        binodal = lambda phi, phi1: TFH.dF(phi, phi1)
        #print(self.PN_binHigh,self.phi_c1[0],'switch')
        phi2a = 1-self.PN_binHigh
        phi1b = self.PN_binLow
        phi2b = 1-self.PN_binLow-1e-5
        for i in range(steps):
            phi2a, phi1b, phi2b = opt.fsolve(binodal, [phi2a, phi1b, phi2b], args = (phi1a_arr[i]))

            #phi1a_arr[i] = 1-phi2a-phi3a[i]
            phi2a_arr[i] = phi2a
            phi1b_arr[i] = phi1b
            phi2b_arr[i] = phi2b
            np.savetxt('phi3a.txt',1-phi1a_arr-phi2a_arr)
            if checkAccuracy(binodal, [phi2a,phi1b,phi2b], args = [phi1a_arr[i]]) < 4:
                print("\n**Warning: Binodal May Be Inaccurate**\n" if not Printed else "", end = "") 
                n+=1
                Printed = True
                
        if Printed:
            print("\tNumber of Binodal Points that did not converge:", n, "\n")
           
        self.phi_b1a = np.vstack([phi1a_arr, phi2a_arr, 1-phi1a_arr-phi2a_arr]).T
        self.phi_b1b = np.vstack([phi1b_arr, phi2b_arr, 1-phi1b_arr-phi2b_arr]).T

    if FM23 and not FM12 and not FM13:
         phi1a_arr = np.linspace(1.e-6,self.phi_c1[0]+1e-3,steps)
         # print(phi3b_arr)
         #phi3a_arr = np.linspace(1e-5,self.NS_binLow,steps)
         #phi3a_arr = np.zeros(steps)
         phi2a_arr = np.zeros(steps)
         phi1b_arr = np.zeros(steps)
         phi2b_arr = np.zeros(steps)
         #print(self.NS_binHigh,self.phi_c1[1],'norm')
         phi2a = self.NS_binHigh
         binodal = lambda phi, phi1: TFH.dF(phi,phi1) 
         phi3a = 1-self.NS_binHigh
         phi2b = self.NS_binLow
         phi3b = 1-self.NS_binLow-1e-5
         phi1b = 1-phi2b-phi3b
         for i in range(steps):
             phi2a, phi1b, phi2b = opt.fsolve(binodal,[phi2a, phi1b, phi2b], args = (phi1a_arr[i]))
             #phi3a_arr[i] = 1-phi1a_arr[i]-phi2a
             phi2a_arr[i] = phi2a
             phi1b_arr[i] = phi1b
             phi2b_arr[i] = phi2b
             #np.savetxt('phi2an.txt',phi2a_arr)
             if checkAccuracy(binodal,[phi3a, phi2b, phi3b], args = [phi2a_arr[i]]) < 4:
                 #r = checkAccuracy(binodal,[phi2b,phi2a,phi3a],args = [phi3b_arr[i]])
                 print('\n**Warning: Binodal May Be Inaccurate**\n' if not Printed else "", end = "")
                 n+=1
                 Printed = True
                 
         if Printed:
             print("\tNumber of Binodal Points that did not converge:", n, "\n")
        # for i in range (steps):
        #    if checkAccuracy(binodal,[phi2a,phi1b,phi2b],args = [phi3a_arr[i]])<4: 
         self.phi_b1a = np.vstack([phi1a_arr, phi2a_arr,1-phi1a_arr-phi2a_arr]).T
         self.phi_b1b = np.vstack([phi1b_arr, phi2b_arr,1-phi1b_arr-phi2b_arr]).T
 

    if FM12 and FM23 and not FM13:
        phi3a = np.linspace(1e-5, self.NS_binHigh-1e-5, steps)
        phi1a_arr = np.zeros(steps)
        phi2a_arr = np.zeros(steps)
        phi1b_arr = np.zeros(steps)
        phi2b_arr = np.zeros(steps)

        binodal = lambda phi, phi3: TFH.dF(phi, 1-phi3-phi[0])

        phi2a = 1-self.PN_binHigh-1e-5
        phi1b = self.PN_binLow-1e-5
        phi2b = 1-self.PN_binLow-1e-5
        
        for i in range(steps):
            phi2a, phi1b, phi2b = opt.fsolve(binodal, ([phi2a, phi1b, phi2b]), args = (phi3a[i]))
            phi1a_arr[i] = 1 - phi3a[i] - phi2a
            phi2a_arr[i] = phi2a
            phi1b_arr[i] = phi1b
            phi2b_arr[i] = phi2b
        
        
            if checkAccuracy(binodal, [phi2a,phi1b,phi2b], args = [phi3a[i]]) < 4:
                print("\n**Warning: Binodal May Be Inaccurate**\n" if not Printed else "", end = "") 
                n+=1
                Printed = True
                
        if Printed:
            print("\tNumber of Binodal Points that did not converge:", n, "\n")
        
        self.phi_b1a = np.vstack([phi1a_arr, phi2a_arr, phi3a]).T
        self.phi_b1b = np.vstack([phi1b_arr, phi2b_arr, 1-phi1b_arr-phi2b_arr]).T

    if FM12 and FM23 and FM13:
        phi1a_arr = np.linspace(self.PN_binHigh,1-1e-5,steps)
        print(phi1a_arr[0],phi1a_arr[steps-2],'hope')
        phi2a_arr = np.zeros(steps)
        phi1b_arr = np.zeros(steps)
        phi2b_arr = np.zeros(steps)

        binodal = lambda phi, phi1: TFH.dF(phi,phi1)

        phi2a =self.PN_binLow
        phi1b =self.PN_binLow
        phi2b =1-self.PN_binLow
 
        for i in range(steps):
              phi2a, phi1b, phi2b = opt.fsolve(binodal,[phi2a, phi1b, phi2b], args = (phi1a_arr[i]))
              #phi3a_arr[i] = 1-phi1a_arr[i]-phi2a
              phi2a_arr[i] = phi2a
              phi1b_arr[i] = phi1b
              phi2b_arr[i] = phi2b

#    self.phi_b1a = np.vstack([phi1a_arr, phi2a_arr,1-phi1a_arr-phi2a_arr]).T
#    self.phi_b1b = np.vstack([phi1b_arr, phi2b_arr,1-phi1b_arr-phi2b_arr]).T

        phi1a_arr2 = np.linspace(1e-17,self.PS_binLow/2,steps)
        phi2a_arr2 = np.zeros(steps)
        phi1b_arr2 = np.zeros(steps)
        phi2b_arr2 = np.zeros(steps)

        binodal = lambda phi, phi1: TFH.dF(phi,phi1)

        phi2a2 =1-self.NS_binHigh
        phi1b2 =self.PN_binLow
        phi2b2 =1-self.NS_binLow

        for i in range(steps):
              phi2a2, phi1b2, phi2b2 = opt.fsolve(binodal,[phi2a2, phi1b2, phi2b2], args = (phi1a_arr2[i]))
              #phi3a_arr[i] = 1-phi1a_arr[i]-phi2a
              phi2a_arr2[i] = phi2a2
              phi1b_arr2[i] = phi1b2
              phi2b_arr2[i] = phi2b2

        self.phi_b1a = np.vstack([phi1a_arr, phi2a_arr,1-phi1a_arr-phi2a_arr]).T
        self.phi_b1b = np.vstack([phi1b_arr, phi2b_arr,1-phi1b_arr-phi2b_arr]).T

        self.phi_b2a = np.vstack([phi1a_arr2, phi2a_arr2,1-phi1a_arr2-phi2a_arr2]).T
        self.phi_b2b = np.vstack([phi1b_arr2, phi2b_arr2,1-phi1b_arr2-phi2b_arr2]).T

setattr(PhaseDiagram, "ternaryBinodalCurves", ternaryBinodalCurves)



#----------------------------------
#### Phase Seperation Analysis ####
#----------------------------------

def PointAnalysis(self):
    phi1, phi2 = self.point
    phi3 = 1 - phi1 - phi2
    
    I_list = []
    
    for i in range(len(self.phi_b1a)):
        points = np.array([self.phi_b1a[i,:], self.phi_b1b[i,:]])
        if phi1 > points[0,0] or phi1 < points[1,0]:
            continue
        f = interp1d(points[:,0],points[:,1])
        g = interp1d(points[:,0],points[:,2])
        if f(phi1) - phi2 < 1e-3 and g(phi1) - phi3 < 1e-3:
            I_list.append(i)
    
    phi1a = 0
    phi2a = 0
    phi1b = 0
    phi2b = 0
    
    for i in I_list:
        phi1a += self.phi_b1a[i,0]
        phi2a += self.phi_b1a[i,1]
        phi1b += self.phi_b1b[i,0]
        phi2b += self.phi_b1b[i,1]
    
    phi1a /= len(I_list)
    phi2a /= len(I_list)
    phi1b /= len(I_list)
    phi2b /= len(I_list)
    
    print("Two Phase Region:")
    print(f"Polymer Phase:     {phi1a:.4}   {phi2a:.4}   {1-phi1a-phi2a:.4}")
    print(f"Nonsolvent Phase:  {phi1b:.4}   {phi2b:.4}   {1-phi1b-phi2b:.4}")
    self.tieLine = np.array([[phi1a,phi2a,1-phi1a-phi2a],[phi1b,phi2b,1-phi1b-phi2b]])
    return
    

setattr(PhaseDiagram, "PointAnalysis", PointAnalysis)

