def plotPhaseDiagram(self):
    plt.figure(frameon=False) #, figsize = (6, 7)
    ax=draw_boundary()
    ax.axis('off') # turn off outside axis and axis lines

    s = self.s

    if s > 0:    
        [xc1, yc1] = project([self.phi_c1[0], self.phi_c1[1], 1-self.phi_c1[0]-self.phi_c1[1]])
        #plt.plot(xc1, yc1, 'go', markersize=5, label = "Critical Points")
    if s > 1:    
        [xc2, yc2] = project([self.phi_c2[0], self.phi_c2[1], 1-self.phi_c2[0]-self.phi_c2[1]])
        #plt.plot(xc2, yc2, 'go', markersize=5)
    if s > 2:    
        [xc3, yc3] = project([self.phi_c3[0], self.phi_c3[1], 1-self.phi_c3[0]-self.phi_c3[1]])
        plt.plot(xc3, yc3, 'go', markersize=5)

    if s > 0: 
        [xs1, ys1] = project(self.phi_s1)
        plt.plot(xs1, ys1, 'r--', linewidth=2, label = "Spinodal") # spinodal
        
    if s > 1:    
        [xs2, ys2] = project(self.phi_s2)
        plt.plot(xs2, ys2, 'y--', linewidth=2)
        
    if s > 2:   
        [xs3, ys3] = project(self.phi_s3)
        plt.plot(xs3, ys3, 'g--', linewidth=2)
        
    if s > 0:  
        print(s,'s')
        [xb1a, yb1a] = project(self.phi_b1a)
        [xb1b, yb1b] = project(self.phi_b1b) 
        plt.plot(xb1a, yb1a, 'b-', linewidth=2, label = "Binodal")
        plt.plot(xb1b, yb1b, 'b-', linewidth=2)
       #np.savetxt('xs.txt',xb1a)
       #np.savetxt('new.txt',self.phi_b1a)


    if s > 1 and 'phi_b2a' in globals():
        print(s,'s')
        [xb2a, yb2a] = project(self.phi_b2a)
        [xb2b, yb2b] = project(self.phi_b2b)
        plt.plot(xb2a, yb2a, 'g-', linewidth=2, label = "Binodal")
        plt.plot(xb2b, yb2b, 'b-', linewidth=2)
    if self.PointBool:
        [tieX, tieY] = project(self.tieLine)
        plt.plot(tieX, tieY, 'b:', linewidth = 1.5)
        
        [pointX, pointY] = project([self.point[0], self.point[1], 1-self.point[0]-self.point[1]])
        plt.plot(pointX, pointY, color = "orange", marker = "s", linewidth = 7)

    else:
        
        [Low1, High1] = project([self.phi_b1a[250,:], self.phi_b1b[250,:]])
        [Low2, High2] = project([self.phi_b1a[1000,:], self.phi_b1b[1000,:]])
        [Low3, High3] = project([self.phi_b1a[1750,:], self.phi_b1b[1750,:]])

        plt.plot(Low1, High1, 'b:', linewidth=1.5, label = "Tie Lines")
        plt.plot(Low2, High2, 'b:', linewidth=1.5)
        plt.plot(Low3, High3, 'b:', linewidth=1.5)
    
        if 'phi_b2a' in globals():
            [Low1b, High1b] = project([self.phi_b2a[250,:], self.phi_b2b[250,:]])
            [Low2b, High2b] = project([self.phi_b2a[1000,:], self.phi_b2b[1000,:]])
            [Low3b, High3b] = project([self.phi_b2a[1750,:], self.phi_b2b[1750,:]])

            plt.plot(Low1b, High1b, 'r:', linewidth=1.5, label = "Tie Lines")
            plt.plot(Low2b, High2b, 'g:', linewidth=1.5)
            plt.plot(Low3b, High3b, 'b:', linewidth=1.5)

    plt.tight_layout(pad=-1)

    plt.savefig("PhaseDiagram.png", dpi = 300, transparent = False)
    return

setattr(PhaseDiagram, "plotPhaseDiagram", plotPhaseDiagram)



